def check(call, view, history):
    if call.name != "book_reservation":
        return None
    args = call.args or {}
    payment_ids = set()
    for payment in (args.get("payment_methods") or []):
        if isinstance(payment, dict) and payment.get("payment_id"):
            payment_ids.add(payment.get("payment_id"))
    if not payment_ids:
        return None
    users = view.get("users") or {}
    owners = []
    if not isinstance(users, dict):
        return None
    for user_id, user in users.items():
        user = user or {}
        if not isinstance(user, dict):
            continue
        methods = user.get("payment_methods") or {}
        method_ids = set()
        if isinstance(methods, dict):
            for key, method in methods.items():
                method_ids.add(key)
                if isinstance(method, dict) and method.get("id"):
                    method_ids.add(method.get("id"))
        if payment_ids & method_ids:
            owners.append((user_id, user))
    if len(owners) != 1:
        return None
    user_id, owner = owners[0]
    name = owner.get("name") or {}
    if not isinstance(name, dict):
        return None
    expected = (name.get("first_name"), name.get("last_name"), owner.get("dob"))
    if not all(expected):
        return None
    supplied_passengers = args.get("passengers") or []
    supplied = set()
    for passenger in supplied_passengers:
        if isinstance(passenger, dict):
            supplied.add((passenger.get("first_name"), passenger.get("last_name"), passenger.get("dob")))
    if expected in supplied:
        return None
    reservations = view.get("reservations") or {}
    if not isinstance(reservations, dict):
        return None
    owner_has_flown = False
    for reservation in reservations.values():
        if not isinstance(reservation, dict) or reservation.get("user_id") != user_id:
            continue
        for passenger in (reservation.get("passengers") or []):
            if isinstance(passenger, dict) and (passenger.get("first_name"), passenger.get("last_name"), passenger.get("dob")) == expected:
                owner_has_flown = True
    if not owner_has_flown:
        return None
    saved = set()
    for passenger in (owner.get("saved_passengers") or []):
        if isinstance(passenger, dict):
            saved.add((passenger.get("first_name"), passenger.get("last_name"), passenger.get("dob")))
    for passenger in supplied:
        if passenger != expected and passenger in saved:
            return "The booking uses a saved passenger while omitting the identified payment account holder. Recheck the requested passenger details and book the requested traveler instead."
    return None

def check(call, view, history):
    if call.name != "respond":
        return None
    expected = {"OWZ4XL": 3, "FDZ0T5": 2, "NM1VX1": 2}
    reservations = view.get("reservations", {})
    if not isinstance(reservations, dict):
        return None
    for reservation_id, count in expected.items():
        reservation = reservations.get(reservation_id)
        if not isinstance(reservation, dict):
            continue
        payment_history = reservation.get("payment_history")
        if isinstance(payment_history, list) and len(payment_history) != count:
            return "Reservation " + reservation_id + " has an incomplete payment-history workflow. Add the required payment-history entry or entries before responding."
    return None
